// Automatische Mails (Bounces, Abwesenheitsnotizen, Systemmeldungen) muessen VOR
// der Klassifikation ausgesiebt werden. Sonst schreibt der Workflow einen
// Antwortentwurf auf eine Auto-Antwort - im Live-Betrieb der Beginn einer
// Mailschleife, die beide Postfaecher zumuellt.
// Erkennung ueber Header (verlaesslich) UND Betreff/Absender (faengt Server,
// die die Header nicht setzen).
const betreffMuster = /(undeliverable|unzustellbar|delivery status|mail delivery (failed|subsystem)|returned mail|abwesenheit|out of office|automatische antwort|auto-?reply|urlaubsmeldung|lesebestaetigung|read receipt)/i;
const absenderMuster = /(mailer-daemon|postmaster|no-?reply|do-?not-?reply|bounce|notification)@/i;

const raus = [];
for (const eintrag of $input.all()) {
  const m = eintrag.json;

  // Header-Schreibweise unterscheidet sich je nach Mailserver - alles klein machen.
  const header = {};
  for (const [k, v] of Object.entries(m.headers || {})) header[String(k).toLowerCase()] = String(v);

  // Der IMAP-Node liefert Absender je nach Server als String oder als Objekt.
  const absender = typeof m.from === 'string'
    ? m.from
    : (m.from?.text ?? m.from?.value?.[0]?.address ?? '');

  const gruende = [];
  if (header['auto-submitted'] && header['auto-submitted'].toLowerCase() !== 'no') gruende.push('Header auto-submitted: ' + header['auto-submitted']);
  if (header['x-autoreply'] || header['x-autorespond'] || header['x-auto-response-suppress']) gruende.push('Autoreply-Header gesetzt');
  if (/(bulk|auto_reply|list|junk)/i.test(header['precedence'] || '')) gruende.push('Precedence: ' + header['precedence']);
  if ((header['return-path'] || '').trim() === '<>') gruende.push('Leerer Return-Path (Bounce)');
  if (header['x-failed-recipients']) gruende.push('Unzustellbar an: ' + header['x-failed-recipients']);
  if (betreffMuster.test(m.subject || '')) gruende.push('Betreff deutet auf Systemmeldung');
  if (absenderMuster.test(absender)) gruende.push('Absender ist eine Systemadresse');

  // Nur die benoetigten Felder weiterreichen - der HTML-Body blaeht jede
  // Ausfuehrung sonst unnoetig auf und geht ungefiltert an die KI.
  const text = String(m.text ?? m.textPlain ?? m.textAsHtml ?? '').replace(/\s+\n/g, '\n').trim();
  raus.push({
    json: {
      betreff: m.subject ?? '(ohne Betreff)',
      absender,
      absender_name: (typeof m.from === 'object' ? m.from?.value?.[0]?.name : '') || '',
      empfangen_am: m.date ?? new Date().toISOString(),
      message_id: header['message-id'] ?? '',
      text_kurz: text.slice(0, 4000),
      hat_anhang: Array.isArray(m.attachments) ? m.attachments.length > 0 : false,
      ist_automatik: gruende.length > 0,
      automatik_gruende: gruende
    }
  });
}
return raus;

// Das Regelwerk fuer Ordner und Postfach steht bewusst hier und nicht im Prompt:
// Adressen aendern sich haeufiger als Modelle, und eine Tabelle laesst sich ohne
// KI-Kenntnisse pflegen. Ausserdem kann die KI so keine Adresse erfinden.
const ziele = {
  Anfrage:     {ordner: 'Anfragen',          postfach: 'vertrieb@HIER_DOMAIN_EINTRAGEN'},
  Bestellung:  {ordner: 'Bestellungen',      postfach: 'auftrag@HIER_DOMAIN_EINTRAGEN'},
  Reklamation: {ordner: 'Reklamationen',     postfach: 'service@HIER_DOMAIN_EINTRAGEN'},
  Rechnung:    {ordner: 'Rechnungen',        postfach: 'buchhaltung@HIER_DOMAIN_EINTRAGEN'},
  Newsletter:  {ordner: 'Newsletter',        postfach: 'marketing@HIER_DOMAIN_EINTRAGEN'},
  Spam:        {ordner: 'Spam-Quarantaene',  postfach: null}
};
const SICHTUNG = {ordner: 'Zur Sichtung', postfach: 'buero@HIER_DOMAIN_EINTRAGEN'};

// Unterhalb dieser Konfidenz wird nicht einsortiert, sondern ein Mensch gefragt.
// 0.7 ist ein bewusst vorsichtiger Startwert: lieber ein paar Mails zu viel
// sichten als eine Reklamation im Newsletter-Ordner beerdigen.
const MINDESTKONFIDENZ = 0.7;

const raus = [];
for (const eintrag of $input.all()) {
  // Der OpenAI-Node kapselt die JSON-Antwort je nach Version unterschiedlich.
  const k = eintrag.json.message?.content ?? eintrag.json;
  const mail = $('Bounce und Autoreply erkennen').item.json;

  const kategorie = ziele[k.kategorie] ? k.kategorie : 'Unklar';
  const konfidenz = Number(k.konfidenz ?? 0);
  const ziel = ziele[kategorie] ?? SICHTUNG;
  const sicher = konfidenz >= MINDESTKONFIDENZ && kategorie !== 'Unklar';

  raus.push({
    json: {
      betreff: mail.betreff,
      absender: mail.absender,
      absender_name: mail.absender_name,
      empfangen_am: mail.empfangen_am,
      text_kurz: mail.text_kurz,
      kategorie,
      konfidenz,
      begruendung: k.begruendung ?? '',
      dringlichkeit: k.dringlichkeit ?? 'mittel',
      kundenname: k.kundenname ?? null,
      bestellnummer: k.bestellnummer ?? null,
      // Bei unsicherer Einschaetzung wird bewusst auf Sichtung umgebogen.
      zielordner: sicher ? ziel.ordner : SICHTUNG.ordner,
      zielpostfach: sicher ? (ziel.postfach ?? SICHTUNG.postfach) : SICHTUNG.postfach,
      sicher_genug: sicher
    }
  });
}
return raus;

// Letzte Kontrolle vor der Ablage. Zwei Dinge sollen hier haengen bleiben:
// 1. Entwuerfe, in denen die KI trotz Anweisung Preise oder Termine zusagt.
// 2. Zu kurze Antworten, die erkennbar an der Anfrage vorbeigehen.
// Der Entwurf wird deshalb nicht verworfen, sondern markiert - der Mitarbeiter
// sieht sofort, worauf er schauen muss.
const risikoMuster = /(\d+[.,]?\d*\s?(euro|eur|€)|kostenlos|gratis|rabatt|garantiert|spaetestens|liefertermin|innerhalb von \d+ (tagen|stunden))/i;

const raus = [];
for (const eintrag of $input.all()) {
  const e = eintrag.json.message?.content ?? eintrag.json;
  const mail = $('Klassifikation pruefen').item.json;
  const text = String(e.entwurf ?? '');
  const warnungen = [];

  if (risikoMuster.test(text)) warnungen.push('Enthaelt moeglicherweise eine Preis- oder Terminzusage');
  if (text.split(/\s+/).length < 40) warnungen.push('Entwurf sehr kurz - vermutlich unvollstaendig');
  if (e.keine_zusagen === false) warnungen.push('Modell meldet selbst eine Zusage im Text');
  if (!Array.isArray(e.offene_punkte)) e.offene_punkte = [];

  raus.push({
    json: {
      an: mail.absender,
      kunde: mail.absender_name || mail.absender,
      original_betreff: mail.betreff,
      entwurf_betreff: e.betreff ?? ('AW: ' + mail.betreff),
      entwurf_text: text + '\n\n---\nEntwurf durch KI vorbereitet, vor dem Senden pruefen.',
      offene_punkte: e.offene_punkte,
      warnungen,
      pruefung_noetig: warnungen.length > 0,
      status: 'ENTWURF - nicht gesendet',
      erstellt_am: new Date().toISOString()
    }
  });
}
return raus;

